/* rf01.sql: periodos y categorias documentales */ CREATE TABLE IF NOT EXISTS periodo (id_periodo INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(50) NOT NULL UNIQUE, fecha_inicio DATE NOT NULL, fecha_fin DATE NOT NULL, estado VARCHAR(10) NOT NULL DEFAULT 'ACTIVO', CONSTRAINT ck_periodo_fechas CHECK (fecha_fin > fecha_inicio), CONSTRAINT ck_periodo_estado CHECK (estado IN ('ACTIVO','CERRADO'))); CREATE TABLE IF NOT EXISTS categoria_documental (id_categoria INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(100) NOT NULL UNIQUE, descripcion TEXT, activa BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT ck_categoria_nombre CHECK (length(trim(nombre)) > 0)); CREATE TABLE IF NOT EXISTS periodo_categoria (id_periodo INTEGER NOT NULL REFERENCES periodo(id_periodo) ON DELETE RESTRICT, id_categoria INTEGER NOT NULL REFERENCES categoria_documental(id_categoria) ON DELETE RESTRICT, PRIMARY KEY (id_periodo, id_categoria)); CREATE INDEX IF NOT EXISTS ix_periodo_categoria_categoria ON periodo_categoria (id_categoria);
